                    <p className="text-sm text-text-secondary mt-0.5">{agent.description}</p>
                  )}
                  <div className="flex items-center gap-3 mt-2">
                    {agent.model && (
                      <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-md font-mono">
                        {agent.model}
                      </span>
                    )}
                    <span className="flex items-center gap-1 text-xs text-text-muted">
                      <Clock className="w-3 h-3" />
                      {new Date(agent.updatedAt).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              </div>
              <button
                onClick={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  handleDelete(agent.filename)
                }}
                className="p-2 rounded-lg text-text-muted hover:text-red hover:bg-red-muted transition-colors opacity-0 group-hover:opacity-100"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

