303	    destDir = path.join(CLAUDE_DIR, 'agents');
304	  } else {
305	    const toPath = Buffer.from(to, 'base64url').toString();
306	    destDir = path.join(toPath, '.claude', 'agents');
307	  }
308	  ensureDir(destDir);
309	  const content = readFileSafe(srcPath);
310	  if (!content) return res.status(404).json({ error: 'Source agent not found' });
311	  fs.writeFileSync(path.join(destDir, agentName + '.md'), content);
312	  res.json({ ok: true });
