321	app.listen(PORT, () => {
322	  console.log('');
323	  console.log('  ╔══════════════════════════════════════╗');
324	  console.log('  ║         Claude Hub is running         ║');
325	  console.log(`  ║     http://localhost:${PORT}            ║`);
326	  console.log('  ╚══════════════════════════════════════╝');
327	  console.log('');
328	  console.log(`  Claude dir: ${CLAUDE_DIR}`);
329	  console.log(`  Config: ${CONFIG_PATH}`);
330	  console.log('');
331	});
