import { Link } from 'react-router-dom'
import { Bot, FolderOpen, FileText, Terminal, ShieldCheck, ArrowRight } from 'lucide-react'
import type { Project } from '../types'

interface Props {
  projects: Project[]
}

export default function Dashboard({ projects }: Props) {
  const totalAgents = projects.reduce((sum, p) => sum + p.agentCount, 0)
  const totalCommands = projects.reduce((sum, p) => sum + p.commands.length, 0)
  const totalRules = projects.reduce((sum, p) => sum + p.rules.length, 0)
  const withClaudeMd = projects.filter((p) => p.hasClaudeMd).length

  const stats = [
    { label: 'Projects', value: projects.length, icon: FolderOpen, color: 'text-accent' },
    { label: 'Agents', value: totalAgents, icon: Bot, color: 'text-purple' },
    { label: 'Commands', value: totalCommands, icon: Terminal, color: 'text-green' },
    { label: 'Rules', value: totalRules, icon: ShieldCheck, color: 'text-amber' },
  ]

  return (
    <div className="p-8 max-w-6xl">
      <div className="mb-8">
        <h1 className="text-2xl font-semibold tracking-tight">Dashboard</h1>
        <p className="text-text-secondary text-sm mt-1">
          Overview of all Claude configurations across your projects
        </p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-4 mb-8">
        {stats.map((s) => (
          <div
            key={s.label}
            className="bg-surface rounded-xl border border-border p-5 flex items-start justify-between"
          >
            <div>
              <p className="text-text-muted text-xs font-medium uppercase tracking-wider">
                {s.label}
              </p>
              <p className="text-3xl font-semibold mt-1 tracking-tight">{s.value}</p>
            </div>
            <div className={`p-2.5 rounded-lg bg-surface-2 ${s.color}`}>
              <s.icon className="w-5 h-5" />
            </div>
          </div>
        ))}
      </div>

      {/* Projects Grid */}
      <div className="mb-4 flex items-center justify-between">
        <h2 className="text-lg font-semibold">Projects</h2>
        <span className="text-xs text-text-muted">
          {withClaudeMd} / {projects.length} with CLAUDE.md
        </span>
      </div>

      {projects.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <FolderOpen className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">No projects found</p>
          <p className="text-text-muted text-sm mt-1">
            Add project directories in{' '}
            <Link to="/settings" className="text-accent hover:text-accent-hover underline">
              Settings
            </Link>
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          {projects.map((p) => (
            <Link
              key={p.id}
              to={`/projects/${p.id}`}
              className="group bg-surface rounded-xl border border-border p-5 hover:border-accent/40 transition-all"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg bg-surface-2">
                    <FolderOpen className="w-4 h-4 text-accent" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-[15px] group-hover:text-accent-hover transition-colors">
                      {p.name}
                    </h3>
                    <p className="text-xs text-text-muted font-mono">{p.displayPath}</p>
                  </div>
                </div>
                <ArrowRight className="w-4 h-4 text-text-muted opacity-0 group-hover:opacity-100 transition-opacity mt-1" />
              </div>

              <div className="flex items-center gap-3 mt-4">
                {p.hasClaudeMd && (
                  <span className="flex items-center gap-1.5 text-xs text-green bg-green-muted px-2 py-1 rounded-md">
                    <FileText className="w-3 h-3" />
                    CLAUDE.md
                  </span>
                )}
                {p.agentCount > 0 && (
                  <span className="flex items-center gap-1.5 text-xs text-purple bg-purple-muted px-2 py-1 rounded-md">
                    <Bot className="w-3 h-3" />
                    {p.agentCount} agent{p.agentCount !== 1 ? 's' : ''}
                  </span>
                )}
                {p.commands.length > 0 && (
                  <span className="flex items-center gap-1.5 text-xs text-amber bg-amber-muted px-2 py-1 rounded-md">
                    <Terminal className="w-3 h-3" />
                    {p.commands.length} cmd{p.commands.length !== 1 ? 's' : ''}
                  </span>
                )}
                {p.rules.length > 0 && (
                  <span className="flex items-center gap-1.5 text-xs text-text-secondary bg-surface-2 px-2 py-1 rounded-md">
                    <ShieldCheck className="w-3 h-3" />
                    {p.rules.length} rule{p.rules.length !== 1 ? 's' : ''}
                  </span>
                )}
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  Bot,
  Plus,
  Trash2,
  Clock,
  Globe,
  FolderOpen,
  Search,
  Filter,
  Copy,
  ArrowRightLeft,
  X,
  ChevronDown,
} from 'lucide-react'
import {
  getUnifiedAgents,
  deleteGlobalAgent,
  deleteProjectAgent,
  copyAgent,
  moveAgent,
  updateGlobalAgent,
} from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedAgent, Project } from '../types'
import { getProjects } from '../lib/api'

export default function AllAgents() {
  const { data: agents, loading, refetch } = useApi(getUnifiedAgents)
  const { data: projects } = useApi(getProjects)
  const navigate = useNavigate()

  const [search, setSearch] = useState('')
  const [scopeFilter, setScopeFilter] = useState<'all' | 'global' | 'project'>('all')
  const [projectFilter, setProjectFilter] = useState<string>('all')
  const [actionAgent, setActionAgent] = useState<UnifiedAgent | null>(null)
  const [actionType, setActionType] = useState<'copy' | 'move' | null>(null)
  const [actionTarget, setActionTarget] = useState<string>('')
  const [creating, setCreating] = useState(false)
  const [newName, setNewName] = useState('')
  const [createScope, setCreateScope] = useState<string>('global')

  const filtered = (agents || []).filter((a) => {
    if (search && !a.name.toLowerCase().includes(search.toLowerCase()) && !a.description.toLowerCase().includes(search.toLowerCase())) return false
    if (scopeFilter === 'global' && a.scope !== 'global') return false
    if (scopeFilter === 'project' && a.scope !== 'project') return false
    if (projectFilter !== 'all' && a.scope === 'project' && a.projectId !== projectFilter) return false
    if (projectFilter !== 'all' && a.scope === 'global' && projectFilter !== 'global') return false
    return true
  })

  // Group by scope
  const globalAgents = filtered.filter((a) => a.scope === 'global')
  const projectGroups = new Map<string, UnifiedAgent[]>()
  for (const a of filtered.filter((a) => a.scope === 'project')) {
    const key = a.projectName || 'Unknown'
    if (!projectGroups.has(key)) projectGroups.set(key, [])
    projectGroups.get(key)!.push(a)
  }

  const handleDelete = async (agent: UnifiedAgent) => {
    if (!confirm(`Delete agent "${agent.name}" from ${agent.scopeLabel}?`)) return
    if (agent.scope === 'global') {
      await deleteGlobalAgent(agent.filename)
    } else {
      await deleteProjectAgent(agent.projectId!, agent.filename)
    }
    refetch()
  }

  const handleAction = async () => {
    if (!actionAgent || !actionType || !actionTarget) return
    const from = actionAgent.scope === 'global' ? 'global' : actionAgent.projectId!
    const to = actionTarget
    if (actionType === 'copy') {
      await copyAgent(from, to, actionAgent.filename)
    } else {
      await moveAgent(from, to, actionAgent.filename)
    }
    setActionAgent(null)
    setActionType(null)
    setActionTarget('')
    refetch()
  }

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = newName.trim().toLowerCase().replace(/\s+/g, '-')
    const template = `---\nname: ${newName.trim()}\ndescription: ""\nmodel: ""\n---\n\n# ${newName.trim()}\n\nWrite your agent instructions here.\n`
    if (createScope === 'global') {
      await updateGlobalAgent(slug, template)
      navigate(`/global/agents/${slug}`)
    } else {
      const { updateProjectAgent } = await import('../lib/api')
      await updateProjectAgent(createScope, slug, template)
      navigate(`/projects/${createScope}/agents/${slug}`)
    }
    setCreating(false)
    setNewName('')
  }

  const projectList = projects || []
  const uniqueProjects = [...new Map(projectList.map((p) => [p.id, p])).values()]

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-6xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Bot className="w-6 h-6 text-purple" />
            All Agents
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            {agents?.length || 0} agents across {projectGroups.size} projects + global
          </p>
        </div>
        <button
          onClick={() => setCreating(true)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" />
          New Agent
        </button>
      </div>

      {/* Filters bar */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search agents..."
            className="w-full bg-surface border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
          />
        </div>

        <div className="flex items-center gap-1 bg-surface border border-border rounded-lg p-0.5">
          {(['all', 'global', 'project'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setScopeFilter(s)}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                scopeFilter === s
                  ? 'bg-accent text-white'
                  : 'text-text-secondary hover:text-text'
              }`}
            >
              {s === 'all' ? 'All' : s === 'global' ? 'Global' : 'Projects'}
            </button>
          ))}
        </div>

        {uniqueProjects.length > 0 && (
          <select
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="bg-surface border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50 appearance-none cursor-pointer"
          >
            <option value="all">All sources</option>
            <option value="global">Global only</option>
            {uniqueProjects.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Create modal */}
      {creating && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">Create New Agent</p>
            <button onClick={() => { setCreating(false); setNewName('') }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="Agent name..."
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <select
              value={createScope}
              onChange={(e) => setCreateScope(e.target.value)}
              className="bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
            >
              <option value="global">Global</option>
              {uniqueProjects.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            <button
              onClick={handleCreate}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
            >
              Create
            </button>
          </div>
        </div>
      )}

      {/* Copy/Move modal */}
      {actionAgent && actionType && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">
              {actionType === 'copy' ? 'Copy' : 'Move'} "{actionAgent.name}" from {actionAgent.scopeLabel}
            </p>
            <button onClick={() => { setActionAgent(null); setActionType(null) }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <select
              value={actionTarget}
              onChange={(e) => setActionTarget(e.target.value)}
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
            >
              <option value="">Select destination...</option>
              {actionAgent.scope !== 'global' && <option value="global">Global</option>}
              {uniqueProjects
                .filter((p) => p.id !== actionAgent.projectId)
                .map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
            </select>
            <button
              onClick={handleAction}
              disabled={!actionTarget}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {actionType === 'copy' ? 'Copy' : 'Move'}
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Bot className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No agents match your search' : 'No agents found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            {search ? 'Try a different search term' : 'Create your first agent to get started'}
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Global agents */}
          {globalAgents.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Globe className="w-4 h-4 text-accent" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  Global
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {globalAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {globalAgents.map((agent) => (
                  <AgentRow
                    key={`global-${agent.filename}`}
                    agent={agent}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Per-project groups */}
          {[...projectGroups.entries()].map(([projectName, projectAgents]) => (
            <div key={projectName}>
              <div className="flex items-center gap-2 mb-3">
                <FolderOpen className="w-4 h-4 text-amber" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  {projectName}
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {projectAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {projectAgents.map((agent) => (
                  <AgentRow
                    key={`${agent.projectId}-${agent.filename}`}
                    agent={agent}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

function AgentRow({
  agent,
  onDelete,
  onCopy,
  onMove,
}: {
  agent: UnifiedAgent
  onDelete: (a: UnifiedAgent) => void
  onCopy: (a: UnifiedAgent) => void
  onMove: (a: UnifiedAgent) => void
}) {
  const editLink =
    agent.scope === 'global'
      ? `/global/agents/${agent.filename}`
      : `/projects/${agent.projectId}/agents/${agent.filename}`

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-xl p-4 hover:border-accent/30 transition-all">
      <Link to={editLink} className="flex items-center gap-4 flex-1 min-w-0">
        <div className="p-2 rounded-lg bg-purple-muted shrink-0">
          <Bot className="w-4 h-4 text-purple" />
        </div>
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-semibold text-sm group-hover:text-accent-hover transition-colors truncate">
              {agent.name}
            </h3>
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded-md font-medium ${
                agent.scope === 'global'
                  ? 'bg-accent-muted text-accent-hover'
                  : 'bg-amber-muted text-amber'
              }`}
            >
              {agent.scopeLabel}
            </span>
          </div>
          {agent.description && (
            <p className="text-xs text-text-secondary mt-0.5 truncate">{agent.description}</p>
          )}
          <div className="flex items-center gap-3 mt-1.5">
            {agent.model && (
              <span className="text-[11px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded font-mono">
                {agent.model}
              </span>
            )}
            <span className="flex items-center gap-1 text-[11px] text-text-muted">
              <Clock className="w-3 h-3" />
              {new Date(agent.updatedAt).toLocaleDateString()}
            </span>
          </div>
        </div>
      </Link>

      {/* Actions */}
      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 ml-3">
        <button
          onClick={(e) => { e.stopPropagation(); onCopy(agent) }}
          title="Copy to..."
          className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted transition-colors"
        >
          <Copy className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onMove(agent) }}
          title="Move to..."
          className="p-1.5 rounded-md text-text-muted hover:text-amber hover:bg-amber-muted transition-colors"
        >
          <ArrowRightLeft className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(agent) }}
          title="Delete"
          className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted transition-colors"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  Bot,
  Plus,
  Trash2,
  Clock,
  Globe,
  FolderOpen,
  Search,
  Copy,
  ArrowRightLeft,
  X,
} from 'lucide-react'
import {
  getUnifiedAgents,
  deleteGlobalAgent,
  deleteProjectAgent,
  copyAgent,
  moveAgent,
  updateGlobalAgent,
} from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedAgent, Project } from '../types'
import { getProjects } from '../lib/api'

export default function AllAgents() {
  const { data: agents, loading, refetch } = useApi(getUnifiedAgents)
  const { data: projects } = useApi(getProjects)
  const navigate = useNavigate()

  const [search, setSearch] = useState('')
  const [scopeFilter, setScopeFilter] = useState<'all' | 'global' | 'project'>('all')
  const [projectFilter, setProjectFilter] = useState<string>('all')
  const [actionAgent, setActionAgent] = useState<UnifiedAgent | null>(null)
  const [actionType, setActionType] = useState<'copy' | 'move' | null>(null)
  const [actionTarget, setActionTarget] = useState<string>('')
  const [creating, setCreating] = useState(false)
  const [newName, setNewName] = useState('')
  const [createScope, setCreateScope] = useState<string>('global')

  const filtered = (agents || []).filter((a) => {
    if (search && !a.name.toLowerCase().includes(search.toLowerCase()) && !a.description.toLowerCase().includes(search.toLowerCase())) return false
    if (scopeFilter === 'global' && a.scope !== 'global') return false
    if (scopeFilter === 'project' && a.scope !== 'project') return false
    if (projectFilter !== 'all' && a.scope === 'project' && a.projectId !== projectFilter) return false
    if (projectFilter !== 'all' && a.scope === 'global' && projectFilter !== 'global') return false
    return true
  })

  // Group by scope
  const globalAgents = filtered.filter((a) => a.scope === 'global')
  const projectGroups = new Map<string, UnifiedAgent[]>()
  for (const a of filtered.filter((a) => a.scope === 'project')) {
    const key = a.projectName || 'Unknown'
    if (!projectGroups.has(key)) projectGroups.set(key, [])
    projectGroups.get(key)!.push(a)
  }

  const handleDelete = async (agent: UnifiedAgent) => {
    if (!confirm(`Delete agent "${agent.name}" from ${agent.scopeLabel}?`)) return
    if (agent.scope === 'global') {
      await deleteGlobalAgent(agent.filename)
    } else {
      await deleteProjectAgent(agent.projectId!, agent.filename)
    }
    refetch()
  }

  const handleAction = async () => {
    if (!actionAgent || !actionType || !actionTarget) return
    const from = actionAgent.scope === 'global' ? 'global' : actionAgent.projectId!
    const to = actionTarget
    if (actionType === 'copy') {
      await copyAgent(from, to, actionAgent.filename)
    } else {
      await moveAgent(from, to, actionAgent.filename)
    }
    setActionAgent(null)
    setActionType(null)
    setActionTarget('')
    refetch()
  }

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = newName.trim().toLowerCase().replace(/\s+/g, '-')
    const template = `---\nname: ${newName.trim()}\ndescription: ""\nmodel: ""\n---\n\n# ${newName.trim()}\n\nWrite your agent instructions here.\n`
    if (createScope === 'global') {
      await updateGlobalAgent(slug, template)
      navigate(`/global/agents/${slug}`)
    } else {
      const { updateProjectAgent } = await import('../lib/api')
      await updateProjectAgent(createScope, slug, template)
      navigate(`/projects/${createScope}/agents/${slug}`)
    }
    setCreating(false)
    setNewName('')
  }

  const projectList = projects || []
  const uniqueProjects = [...new Map(projectList.map((p) => [p.id, p])).values()]

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-6xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Bot className="w-6 h-6 text-purple" />
            All Agents
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            {agents?.length || 0} agents across {projectGroups.size} projects + global
          </p>
        </div>
        <button
          onClick={() => setCreating(true)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" />
          New Agent
        </button>
      </div>

      {/* Filters bar */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search agents..."
            className="w-full bg-surface border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
          />
        </div>

        <div className="flex items-center gap-1 bg-surface border border-border rounded-lg p-0.5">
          {(['all', 'global', 'project'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setScopeFilter(s)}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                scopeFilter === s
                  ? 'bg-accent text-white'
                  : 'text-text-secondary hover:text-text'
              }`}
            >
              {s === 'all' ? 'All' : s === 'global' ? 'Global' : 'Projects'}
            </button>
          ))}
        </div>

        {uniqueProjects.length > 0 && (
          <select
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="bg-surface border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50 appearance-none cursor-pointer"
          >
            <option value="all">All sources</option>
            <option value="global">Global only</option>
            {uniqueProjects.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Create modal */}
      {creating && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">Create New Agent</p>
            <button onClick={() => { setCreating(false); setNewName('') }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="Agent name..."
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <select
              value={createScope}
              onChange={(e) => setCreateScope(e.target.value)}
              className="bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
            >
              <option value="global">Global</option>
              {uniqueProjects.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            <button
              onClick={handleCreate}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
            >
              Create
            </button>
          </div>
        </div>
      )}

      {/* Copy/Move modal */}
      {actionAgent && actionType && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">
              {actionType === 'copy' ? 'Copy' : 'Move'} "{actionAgent.name}" from {actionAgent.scopeLabel}
            </p>
            <button onClick={() => { setActionAgent(null); setActionType(null) }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <select
              value={actionTarget}
              onChange={(e) => setActionTarget(e.target.value)}
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
            >
              <option value="">Select destination...</option>
              {actionAgent.scope !== 'global' && <option value="global">Global</option>}
              {uniqueProjects
                .filter((p) => p.id !== actionAgent.projectId)
                .map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
            </select>
            <button
              onClick={handleAction}
              disabled={!actionTarget}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {actionType === 'copy' ? 'Copy' : 'Move'}
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Bot className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No agents match your search' : 'No agents found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            {search ? 'Try a different search term' : 'Create your first agent to get started'}
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Global agents */}
          {globalAgents.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Globe className="w-4 h-4 text-accent" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  Global
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {globalAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {globalAgents.map((agent) => (
                  <AgentRow
                    key={`global-${agent.filename}`}
                    agent={agent}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Per-project groups */}
          {[...projectGroups.entries()].map(([projectName, projectAgents]) => (
            <div key={projectName}>
              <div className="flex items-center gap-2 mb-3">
                <FolderOpen className="w-4 h-4 text-amber" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  {projectName}
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {projectAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {projectAgents.map((agent) => (
                  <AgentRow
                    key={`${agent.projectId}-${agent.filename}`}
                    agent={agent}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

function AgentRow({
  agent,
  onDelete,
  onCopy,
  onMove,
}: {
  agent: UnifiedAgent
  onDelete: (a: UnifiedAgent) => void
  onCopy: (a: UnifiedAgent) => void
  onMove: (a: UnifiedAgent) => void
}) {
  const editLink =
    agent.scope === 'global'
      ? `/global/agents/${agent.filename}`
      : `/projects/${agent.projectId}/agents/${agent.filename}`

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-xl p-4 hover:border-accent/30 transition-all">
      <Link to={editLink} className="flex items-center gap-4 flex-1 min-w-0">
        <div className="p-2 rounded-lg bg-purple-muted shrink-0">
          <Bot className="w-4 h-4 text-purple" />
        </div>
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-semibold text-sm group-hover:text-accent-hover transition-colors truncate">
              {agent.name}
            </h3>
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded-md font-medium ${
                agent.scope === 'global'
                  ? 'bg-accent-muted text-accent-hover'
                  : 'bg-amber-muted text-amber'
              }`}
            >
              {agent.scopeLabel}
            </span>
          </div>
          {agent.description && (
            <p className="text-xs text-text-secondary mt-0.5 truncate">{agent.description}</p>
          )}
          <div className="flex items-center gap-3 mt-1.5">
            {agent.model && (
              <span className="text-[11px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded font-mono">
                {agent.model}
              </span>
            )}
            <span className="flex items-center gap-1 text-[11px] text-text-muted">
              <Clock className="w-3 h-3" />
              {new Date(agent.updatedAt).toLocaleDateString()}
            </span>
          </div>
        </div>
      </Link>

      {/* Actions */}
      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 ml-3">
        <button
          onClick={(e) => { e.stopPropagation(); onCopy(agent) }}
          title="Copy to..."
          className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted transition-colors"
        >
          <Copy className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onMove(agent) }}
          title="Move to..."
          className="p-1.5 rounded-md text-text-muted hover:text-amber hover:bg-amber-muted transition-colors"
        >
          <ArrowRightLeft className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(agent) }}
          title="Delete"
          className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted transition-colors"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

import { useState } from 'react'
import { Link } from 'react-router-dom'
import { Terminal, Search, FolderOpen, Clock, ChevronDown, ChevronRight } from 'lucide-react'
import { getUnifiedCommands } from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedCommand } from '../types'

export default function AllCommands() {
  const { data: commands, loading } = useApi(getUnifiedCommands)
  const [search, setSearch] = useState('')
  const [expanded, setExpanded] = useState<string | null>(null)
  const [projectFilter, setProjectFilter] = useState<string>('all')

  const filtered = (commands || []).filter((c) => {
    if (search && !c.name.toLowerCase().includes(search.toLowerCase())) return false
    if (projectFilter !== 'all' && c.projectId !== projectFilter) return false
    return true
  })

  // Group by project
  const groups = new Map<string, UnifiedCommand[]>()
  for (const cmd of filtered) {
    const key = cmd.projectName
    if (!groups.has(key)) groups.set(key, [])
    groups.get(key)!.push(cmd)
  }

  // Unique projects for filter
  const projectNames = [...new Set((commands || []).map((c) => ({ id: c.projectId, name: c.projectName })))]
  const uniqueProjects = [...new Map(projectNames.map((p) => [p.id, p])).values()]

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-6xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Terminal className="w-6 h-6 text-amber" />
            All Commands
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            {commands?.length || 0} slash commands across all projects
          </p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search commands..."
            className="w-full bg-surface border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
          />
        </div>
        {uniqueProjects.length > 1 && (
          <select
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="bg-surface border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
          >
            <option value="all">All projects</option>
            {uniqueProjects.map((p) => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        )}
      </div>

      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Terminal className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No commands match your search' : 'No commands found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            Add .md files to .claude/commands/ in your projects
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {[...groups.entries()].map(([projectName, cmds]) => (
            <div key={projectName}>
              <div className="flex items-center gap-2 mb-3">
                <FolderOpen className="w-4 h-4 text-amber" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  {projectName}
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {cmds.length}
                </span>
              </div>
              <div className="space-y-2">
                {cmds.map((cmd) => {
                  const key = `${cmd.projectId}-${cmd.name}`
                  const isExpanded = expanded === key
                  return (
                    <div
                      key={key}
                      className="bg-surface border border-border rounded-xl overflow-hidden"
                    >
                      <button
                        onClick={() => setExpanded(isExpanded ? null : key)}
                        className="w-full flex items-center justify-between px-4 py-3 text-left hover:bg-surface-2 transition-colors"
                      >
                        <div className="flex items-center gap-3">
                          <Terminal className="w-4 h-4 text-amber shrink-0" />
                          <span className="font-medium text-sm font-mono">/{cmd.name}</span>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="flex items-center gap-1 text-[11px] text-text-muted">
                            <Clock className="w-3 h-3" />
                            {new Date(cmd.updatedAt).toLocaleDateString()}
                          </span>
                          {isExpanded ? (
                            <ChevronDown className="w-4 h-4 text-text-muted" />
                          ) : (
                            <ChevronRight className="w-4 h-4 text-text-muted" />
                          )}
                        </div>
                      </button>
                      {isExpanded && (
                        <div className="border-t border-border p-4 bg-surface-2">
                          <pre className="text-sm text-text-secondary font-mono whitespace-pre-wrap leading-relaxed">
                            {cmd.content}
                          </pre>
                        </div>
                      )}
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

