import { useState, useEffect } from 'react'
import {
  FolderOpen,
  FolderCheck,
  ChevronRight,
  ArrowUp,
  X,
  Check,
  Loader2,
  Home,
} from 'lucide-react'
import { browseDirectory, type BrowseResult } from '../lib/api'

interface Props {
  open: boolean
  onClose: () => void
  onSelect: (path: string) => void
  existingDirs: string[]
}

export default function DirectoryPicker({ open, onClose, onSelect, existingDirs }: Props) {
  const [data, setData] = useState<BrowseResult | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [selected, setSelected] = useState<string | null>(null)

  const navigate = (dirPath?: string) => {
    setLoading(true)
    setError(null)
    setSelected(null)
    browseDirectory(dirPath)
      .then(setData)
      .catch(() => setError('Cannot access this directory'))
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    if (open) {
      navigate()
    }
  }, [open])

  if (!open) return null

  const isAlreadyAdded = (dirPath: string) =>
    existingDirs.some((d) => d === dirPath || d === dirPath.replace(/^\/Users\/[^/]+/, '~'))

  const handleSelect = () => {
    if (selected) {
      onSelect(selected)
      onClose()
    }
  }

  const handleSelectCurrent = () => {
    if (data) {
      onSelect(data.current)
      onClose()
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

      {/* Modal */}
      <div className="relative bg-surface border border-border rounded-2xl shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col">
        {/* Header */}
