    setLoading(true)
    setError(null)
    setSelected(null)
    browseDirectory(dirPath)
      .then(setData)
      .catch(() => setError('Cannot access this directory'))
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    if (open) {
      navigate()
    }
