import { Link } from 'react-router-dom'
import {
  Bot,
  FolderOpen,
  FileText,
  Terminal,
  ShieldCheck,
  ArrowRight,
  Settings,
} from 'lucide-react'
import type { Project } from '../types'
import { getUnifiedAgents } from '../lib/api'
import { useApi } from '../hooks/useApi'

interface Props {
  projects: Project[]
}

export default function Dashboard({ projects }: Props) {
  const { data: allAgents } = useApi(getUnifiedAgents)

  const totalAgents = allAgents?.length || 0
  const globalAgents = allAgents?.filter((a) => a.scope === 'global').length || 0
  const totalCommands = projects.reduce((sum, p) => sum + p.commands.length, 0)
  const totalRules = projects.reduce((sum, p) => sum + p.rules.length, 0)

  const stats = [
    { label: 'Projects', value: projects.length, icon: FolderOpen, color: 'text-accent', bg: 'bg-accent-muted', link: '/settings' },
    { label: 'Total Agents', value: totalAgents, sub: `${globalAgents} global`, icon: Bot, color: 'text-purple', bg: 'bg-purple-muted', link: '/agents' },
    { label: 'Commands', value: totalCommands, icon: Terminal, color: 'text-amber', bg: 'bg-amber-muted', link: '/commands' },
    { label: 'Rules', value: totalRules, icon: ShieldCheck, color: 'text-green', bg: 'bg-green-muted', link: '/rules' },
  ]

  return (
    <div className="p-8 max-w-6xl">
      <div className="mb-8">
        <h1 className="text-2xl font-semibold tracking-tight">Dashboard</h1>
        <p className="text-text-secondary text-sm mt-1">
          Central hub for all your Claude agents, commands, and configurations
        </p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-4 mb-8">
        {stats.map((s) => (
          <Link
            key={s.label}
            to={s.link}
            className="bg-surface rounded-xl border border-border p-5 flex items-start justify-between hover:border-accent/30 transition-all group"
          >
            <div>
              <p className="text-text-muted text-xs font-medium uppercase tracking-wider">
                {s.label}
              </p>
              <p className="text-3xl font-semibold mt-1 tracking-tight">{s.value}</p>
              {'sub' in s && s.sub && (
                <p className="text-xs text-text-muted mt-0.5">{s.sub}</p>
              )}
            </div>
            <div className={`p-2.5 rounded-lg ${s.bg} ${s.color}`}>
              <s.icon className="w-5 h-5" />
            </div>
          </Link>
        ))}
      </div>

      {/* Projects Grid */}
      {projects.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <FolderOpen className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">No projects found</p>
          <p className="text-text-muted text-sm mt-1 mb-4">
            Add project directories to start managing your Claude configs
          </p>
          <Link
            to="/settings"
            className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
          >
            <Settings className="w-4 h-4" />
            Open Settings
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          {projects.map((p) => (
            <Link
              key={p.id}
              to={`/projects/${p.id}`}
              className="group bg-surface rounded-xl border border-border p-5 hover:border-accent/30 transition-all"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3 min-w-0">
                  <div className="p-2 rounded-lg bg-surface-2 shrink-0">
                    <FolderOpen className="w-4 h-4 text-accent" />
                  </div>
                  <div className="min-w-0">
                    <h3 className="font-semibold text-[15px] group-hover:text-accent-hover transition-colors truncate">
                      {p.name}
                    </h3>
                    <p className="text-xs text-text-muted font-mono truncate">{p.displayPath}</p>
                  </div>
                </div>
                <ArrowRight className="w-4 h-4 text-text-muted opacity-0 group-hover:opacity-100 transition-opacity shrink-0 mt-1" />
              </div>

              <div className="flex items-center gap-3 mt-4">
                {p.hasClaudeMd && (
                  <span className="flex items-center gap-1.5 text-xs text-green bg-green-muted px-2 py-1 rounded-md">
                    <FileText className="w-3 h-3" />
                    CLAUDE.md
                  </span>
                )}
                {p.agentCount > 0 && (
                  <span className="flex items-center gap-1.5 text-xs text-purple bg-purple-muted px-2 py-1 rounded-md">
                    <Bot className="w-3 h-3" />
                    {p.agentCount} agent{p.agentCount !== 1 ? 's' : ''}
                  </span>
                )}
                {p.commands.length > 0 && (
                  <span className="flex items-center gap-1.5 text-xs text-amber bg-amber-muted px-2 py-1 rounded-md">
                    <Terminal className="w-3 h-3" />
                    {p.commands.length} cmd{p.commands.length !== 1 ? 's' : ''}
                  </span>
                )}
                {p.rules.length > 0 && (
                  <span className="flex items-center gap-1.5 text-xs text-text-secondary bg-surface-2 px-2 py-1 rounded-md">
                    <ShieldCheck className="w-3 h-3" />
                    {p.rules.length} rule{p.rules.length !== 1 ? 's' : ''}
                  </span>
                )}
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

