import { useState, useRef, useEffect } from 'react'
import { X, Send, Sparkles, Copy, Check, RefreshCw } from 'lucide-react'
import type { AiMessage } from '../lib/api'
import { sendAiChat } from '../lib/api'

export type AiContext = 'agent' | 'command' | 'rule' | 'claude-md'

interface Props {
  open: boolean
  onClose: () => void
  context: AiContext
  currentContent: string
  onApply: (content: string) => void
  contextLabel?: string
}

const SYSTEM_PROMPTS: Record<AiContext, string> = {
  agent: `You are an expert Claude Code agent designer. Help users write and improve their Claude subagent .md files.
A Claude agent file uses YAML frontmatter with fields: name, description, model (sonnet/opus/haiku), tools (comma-separated tool names).
After the frontmatter is the agent's system prompt — detailed instructions for what the agent does.
Be concrete, use imperative language, and write production-grade agent prompts. When writing complete agents, always include the full frontmatter + instructions.`,
  command: `You are an expert Claude Code slash command designer. Help users write and improve their project slash commands.
Slash commands are markdown files that define what happens when a user types /<commandname> in Claude Code.
The content becomes the prompt that Claude receives. Use $ARGUMENTS as a placeholder for user-provided arguments.
Write clear, actionable command prompts that are scoped and effective.`,
  rule: `You are an expert Claude Code rules designer. Help users write and improve their project rules.
Rules are markdown files that define persistent behaviors and constraints for Claude in a specific project.
They are always loaded into context. Write concise, actionable rules that help Claude work better in the project.`,
  'claude-md': `You are an expert at writing CLAUDE.md files — the primary instruction file Claude reads at the start of every session.
Help users write and improve their global or project CLAUDE.md.
Good CLAUDE.md files include: project context, tech stack, coding conventions, key architectural decisions, and behavioral guidelines.
Be specific, practical, and use markdown headings for organization.`,
}

const CONTEXT_LABELS: Record<AiContext, string> = {
  agent: 'Agent',
  command: 'Slash Command',
  rule: 'Rule',
  'claude-md': 'CLAUDE.md',
}

export default function AiAssistant({ open, onClose, context, currentContent, onApply, contextLabel }: Props) {
  const [messages, setMessages] = useState<AiMessage[]>([])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [copiedIdx, setCopiedIdx] = useState<number | null>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    if (open) {
      // Reset on open with a fresh greeting
      setMessages([])
      setError('')
      setTimeout(() => inputRef.current?.focus(), 100)
    }
  }, [open])

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const buildSystemPrompt = () => {
    let sys = SYSTEM_PROMPTS[context]
    if (currentContent.trim()) {
      sys += `\n\nCurrent ${CONTEXT_LABELS[context]} content the user is editing:\n\`\`\`\n${currentContent}\n\`\`\``
    }
    return sys
  }

  const send = async () => {
    const text = input.trim()
    if (!text || loading) return

    const newMessages: AiMessage[] = [...messages, { role: 'user', content: text }]
    setMessages(newMessages)
    setInput('')
    setLoading(true)
    setError('')

    try {
      const { content } = await sendAiChat(newMessages, buildSystemPrompt())
      setMessages([...newMessages, { role: 'assistant', content }])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to get response')
    } finally {
      setLoading(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      send()
    }
  }

  const copyToClipboard = (text: string, idx: number) => {
    navigator.clipboard.writeText(text)
    setCopiedIdx(idx)
    setTimeout(() => setCopiedIdx(null), 2000)
  }

  const extractCode = (text: string): string => {
    // Try to extract content from a code block, else return full text
    const match = text.match(/```(?:\w+)?\n([\s\S]+?)```/)
    return match ? match[1].trim() : text.trim()
  }

  const label = contextLabel || CONTEXT_LABELS[context]

  if (!open) return null

  return (
    <div className="fixed inset-y-0 right-0 z-50 flex">
      {/* Backdrop */}
      <div className="fixed inset-0 bg-black/20" onClick={onClose} />

      {/* Panel */}
      <div className="relative ml-auto w-[420px] bg-surface border-l border-border flex flex-col shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 rounded-lg bg-purple-muted flex items-center justify-center">
              <Sparkles className="w-4 h-4 text-purple" />
            </div>
            <div>
              <p className="text-sm font-semibold">AI Assist</p>
              <p className="text-[11px] text-text-muted">Helping with: {label}</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4">
          {messages.length === 0 && (
            <div className="text-center pt-6">
              <div className="w-12 h-12 rounded-xl bg-purple-muted flex items-center justify-center mx-auto mb-3">
                <Sparkles className="w-6 h-6 text-purple" />
              </div>
              <p className="text-sm font-medium text-text-secondary mb-1">
                Claude AI Assistant
              </p>
              <p className="text-xs text-text-muted mb-5">
                Ask me to write, improve, or explain your {label}.
              </p>
              <div className="space-y-2 text-left">
                {getSuggestions(context).map((s) => (
                  <button
                    key={s}
                    onClick={() => setInput(s)}
                    className="w-full text-left text-xs px-3 py-2 rounded-lg bg-surface-2 text-text-secondary hover:bg-accent-muted hover:text-accent-hover transition-colors"
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
          )}

          {messages.map((msg, idx) => (
            <div key={idx} className={`flex gap-2.5 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              {msg.role === 'assistant' && (
                <div className="w-6 h-6 rounded-md bg-purple-muted flex items-center justify-center shrink-0 mt-0.5">
                  <Sparkles className="w-3.5 h-3.5 text-purple" />
                </div>
              )}
              <div
                className={`max-w-[85%] rounded-xl px-3.5 py-2.5 text-sm ${
                  msg.role === 'user'
                    ? 'bg-accent text-white rounded-br-sm'
                    : 'bg-surface-2 text-text rounded-bl-sm'
                }`}
              >
                <pre className="whitespace-pre-wrap font-sans text-[13px] leading-relaxed break-words">
                  {msg.content}
                </pre>
                {msg.role === 'assistant' && (
                  <div className="flex items-center gap-2 mt-2.5 pt-2.5 border-t border-border">
                    <button
                      onClick={() => copyToClipboard(msg.content, idx)}
                      className="flex items-center gap-1.5 text-[11px] text-text-muted hover:text-text transition-colors"
                    >
                      {copiedIdx === idx ? (
                        <Check className="w-3.5 h-3.5 text-green" />
                      ) : (
                        <Copy className="w-3.5 h-3.5" />
                      )}
                      {copiedIdx === idx ? 'Copied' : 'Copy'}
                    </button>
                    <button
                      onClick={() => onApply(extractCode(msg.content))}
                      className="flex items-center gap-1.5 text-[11px] px-2 py-0.5 rounded bg-accent text-white hover:bg-accent-hover transition-colors ml-auto"
                    >
                      Apply to editor
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))}

          {loading && (
            <div className="flex gap-2.5 justify-start">
              <div className="w-6 h-6 rounded-md bg-purple-muted flex items-center justify-center shrink-0 mt-0.5">
                <RefreshCw className="w-3.5 h-3.5 text-purple animate-spin" />
              </div>
              <div className="bg-surface-2 rounded-xl rounded-bl-sm px-3.5 py-2.5">
                <div className="flex gap-1.5 items-center h-5">
                  <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:0ms]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:150ms]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:300ms]" />
                </div>
              </div>
            </div>
          )}

          {error && (
            <div className="bg-red-muted border border-red/20 rounded-xl px-4 py-3 text-sm text-red">
              {error}
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="px-4 py-4 border-t border-border shrink-0">
          <div className="flex gap-2 items-end">
            <textarea
              ref={inputRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={`Ask Claude about your ${label}...`}
              rows={2}
              className="flex-1 bg-surface-2 border border-border rounded-xl px-3.5 py-2.5 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted"
            />
            <button
              onClick={send}
              disabled={!input.trim() || loading}
              className="p-2.5 bg-accent text-white rounded-xl hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors shrink-0"
            >
              <Send className="w-4 h-4" />
            </button>
          </div>
          <p className="text-[11px] text-text-muted mt-2">
            Enter to send · Shift+Enter for new line
          </p>
        </div>
      </div>
    </div>
  )
}

function getSuggestions(context: AiContext): string[] {
  switch (context) {
    case 'agent':
      return [
        'Write a complete agent for code review',
        'Improve my current agent description',
        'What tools should this agent use?',
        'Make the instructions more specific',
      ]
    case 'command':
      return [
        'Write a command to generate unit tests',
        'Improve this command to be more specific',
        'How should I use $ARGUMENTS here?',
        'Write a PR description command',
      ]
    case 'rule':
      return [
        'Write rules for a React TypeScript project',
        'Add a rule about code style',
        'What rules help Claude work better?',
        'Improve clarity of my current rules',
      ]
    case 'claude-md':
      return [
        'Write a CLAUDE.md for a Next.js project',
        'Add tech stack section',
        'Improve the architecture description',
        'What should every CLAUDE.md include?',
      ]
  }
}

