          spellCheck={false}
        />
      </div>

      <AiAssistant
        open={aiOpen}
        onClose={() => setAiOpen(false)}
        context="rule"
        currentContent={content}
        contextLabel={name}
        onApply={(text) => {
          setContent(text)
          setDirty(true)
          setAiOpen(false)
        }}
      />
    </div>
  )
}

