// 6 — Eye/Lens: iris with inner glow
function IconEye({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M7 20 C11 13 15.5 10 20 10 C24.5 10 29 13 33 20 C29 27 24.5 30 20 30 C15.5 30 11 27 7 20 Z" fill="white" opacity="0.12" stroke="white" strokeWidth="1.5" />
      <circle cx="20" cy="20" r="5.5" fill="white" opacity="0.9" />
      <circle cx="22" cy="17.5" r="1.5" fill="white" opacity="0.6" />
      <circle cx="20" cy="20" r="2.5" fill="white" opacity="0.2" />
    </svg>
  )
}

// 7 — Compass Star: eight-point star with center
function IconCompass({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M20 8 L20 32" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <path d="M8 20 L32 20" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <path d="M11.5 11.5 L28.5 28.5" stroke="white" strokeWidth="1" opacity="0.3" />
      <path d="M28.5 11.5 L11.5 28.5" stroke="white" strokeWidth="1" opacity="0.3" />
      <circle cx="20" cy="20" r="5" stroke="white" strokeWidth="1.5" opacity="0.6" fill="none" />
      <circle cx="20" cy="20" r="2.5" fill="white" opacity="0.95" />
    </svg>
  )
}

const ICON_TYPES = [
  IconOrb, IconGem, IconNetwork, IconSpiral,
  IconLightning, IconWaves, IconEye, IconCompass,
]

interface AgentIconProps {
  name: string
  /** A unique key to namespace gradient IDs when the same name appears multiple times */
  uid?: string
  className?: string
  size?: number
}

export default function AgentIcon({ name, uid, className = '', size = 40 }: AgentIconProps) {
  const h = nameHash(name)
  const IconComp = ICON_TYPES[h % ICON_TYPES.length]
  const [c1, c2] = PALETTES[(h >> 4) % PALETTES.length]
  // Use uid if provided, else use sanitised name (safe for SVG IDs as long as names are unique on page)
  const safeId = (uid || name).replace(/[^a-z0-9]/gi, '-').slice(0, 28)

  return (
    <div
      className={`shrink-0 rounded-xl shadow-sm overflow-hidden ${className}`}
      style={{ width: size, height: size }}
    >
      <IconComp id={safeId} c1={c1} c2={c2} />
    </div>
  )
}

