/**
 * AgentIcon — Illustrated SVG agent icons, Relevance-AI style.
 * Each agent gets a deterministic icon type + gradient color pair based on its name.
 */

const PALETTES: [string, string][] = [
  ['#7c3aed', '#4f46e5'], // violet → indigo
  ['#ec4899', '#f97316'], // pink → orange
  ['#10b981', '#0891b2'], // emerald → cyan
  ['#0ea5e9', '#6366f1'], // sky → indigo
  ['#f59e0b', '#ef4444'], // amber → red
  ['#14b8a6', '#3b82f6'], // teal → blue
  ['#a855f7', '#ec4899'], // purple → pink
  ['#f97316', '#facc15'], // orange → yellow
  ['#06b6d4', '#8b5cf6'], // cyan → violet
  ['#84cc16', '#14b8a6'], // lime → teal
]

function nameHash(name: string): number {
  let h = 0
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xffff
  return h
}

type DrawProps = { id: string; c1: string; c2: string }

function BgRect({ id, c1, c2, rx = 12 }: DrawProps & { rx?: number }) {
  const gid = `${id}-bg`
  return (
    <>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse">
          <stop stopColor={c1} />
          <stop offset="1" stopColor={c2} />
        </linearGradient>
      </defs>
      <rect width="40" height="40" rx={rx} fill={`url(#${gid})`} />
    </>
  )
}

