/**
 * AgentIcon — Illustrated SVG agent icons, Relevance-AI style.
 * Each agent gets a deterministic icon type + gradient color pair based on its name.
 */

const PALETTES: [string, string][] = [
  ['#7c3aed', '#4f46e5'], // violet → indigo
  ['#ec4899', '#f97316'], // pink → orange
  ['#10b981', '#0891b2'], // emerald → cyan
  ['#0ea5e9', '#6366f1'], // sky → indigo
  ['#f59e0b', '#ef4444'], // amber → red
  ['#14b8a6', '#3b82f6'], // teal → blue
  ['#a855f7', '#ec4899'], // purple → pink
  ['#f97316', '#facc15'], // orange → yellow
  ['#06b6d4', '#8b5cf6'], // cyan → violet
  ['#84cc16', '#14b8a6'], // lime → teal
]

function nameHash(name: string): number {
  let h = 0
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xffff
  return h
}

type DrawProps = { id: string; c1: string; c2: string }

function BgRect({ id, c1, c2, rx = 12 }: DrawProps & { rx?: number }) {
  const gid = `${id}-bg`
  return (
    <>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse">
          <stop stopColor={c1} />
          <stop offset="1" stopColor={c2} />
        </linearGradient>
      </defs>
      <rect width="40" height="40" rx={rx} fill={`url(#${gid})`} />
    </>
  )
}

// 0 — Radiant Orb: glowing sphere with orbital ring
function IconOrb({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <circle cx="20" cy="20" r="10" fill="white" opacity="0.1" />
      <circle cx="20" cy="20" r="6" fill="white" opacity="0.95" />
      <ellipse cx="20" cy="20" rx="11.5" ry="4.5" stroke="white" strokeWidth="1.5" opacity="0.45" transform="rotate(-25 20 20)" />
      <circle cx="16.5" cy="16.5" r="1.5" fill="white" opacity="0.75" />
    </svg>
  )
}

// 1 — Crystal/Gem: diamond with facets
function IconGem({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M20 8 L31 20 L20 32 L9 20 Z" fill="white" opacity="0.15" stroke="white" strokeWidth="1.5" />
      <path d="M20 8 L9 20 M20 8 L31 20" stroke="white" strokeWidth="1" opacity="0.55" />
      <path d="M9 20 L20 15 L31 20" stroke="white" strokeWidth="1" opacity="0.55" />
      <circle cx="20" cy="17.5" r="2" fill="white" opacity="0.9" />
    </svg>
  )
}

// 2 — Neural Network: nodes with connections
function IconNetwork({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <line x1="20" y1="20" x2="10" y2="12" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <line x1="20" y1="20" x2="30" y2="12" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <line x1="20" y1="20" x2="11" y2="28" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <line x1="20" y1="20" x2="29" y2="28" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <line x1="10" y1="12" x2="30" y2="12" stroke="white" strokeWidth="1" opacity="0.25" />
      <circle cx="20" cy="20" r="4" fill="white" opacity="0.95" />
      <circle cx="10" cy="12" r="2.5" fill="white" opacity="0.8" />
      <circle cx="30" cy="12" r="2.5" fill="white" opacity="0.8" />
      <circle cx="11" cy="28" r="2.5" fill="white" opacity="0.8" />
      <circle cx="29" cy="28" r="2.5" fill="white" opacity="0.8" />
    </svg>
  )
}

// 3 — Vortex/Spiral: concentric arcs
function IconSpiral({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M20 20 C20 14.5 25.5 14.5 25.5 20 C25.5 25.5 14.5 25.5 14.5 20 C14.5 14.5 18 11 20 10" stroke="white" strokeWidth="2" fill="none" opacity="0.75" strokeLinecap="round" />
      <path d="M20 20 C20 11 29 11 29 20 C29 29 11 29 11 20 C11 12 16 8.5 20 8" stroke="white" strokeWidth="1.5" fill="none" opacity="0.4" strokeLinecap="round" />
      <circle cx="20" cy="20" r="2.5" fill="white" opacity="0.95" />
    </svg>
  )
}

// 4 — Lightning: bolt with particle sparks
function IconLightning({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M23 8 L13 21 L19.5 21 L17 32 L27 19 L20.5 19 Z" fill="white" opacity="0.95" />
      <circle cx="29" cy="11" r="1.5" fill="white" opacity="0.6" />
      <circle cx="10" cy="26" r="1.5" fill="white" opacity="0.55" />
      <circle cx="30" cy="28" r="1" fill="white" opacity="0.45" />
    </svg>
  )
}

// 5 — Wave/Flow: three flowing sine curves
function IconWaves({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M7 14 C11 10 15 10 20 14 C25 18 29 18 33 14" stroke="white" strokeWidth="2.5" fill="none" opacity="0.9" strokeLinecap="round" />
      <path d="M7 20 C11 16 15 16 20 20 C25 24 29 24 33 20" stroke="white" strokeWidth="2" fill="none" opacity="0.55" strokeLinecap="round" />
      <path d="M7 26 C11 22 15 22 20 26 C25 30 29 30 33 26" stroke="white" strokeWidth="1.5" fill="none" opacity="0.3" strokeLinecap="round" />
    </svg>
  )
}

// 6 — Eye/Lens: iris with inner glow
function IconEye({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M7 20 C11 13 15.5 10 20 10 C24.5 10 29 13 33 20 C29 27 24.5 30 20 30 C15.5 30 11 27 7 20 Z" fill="white" opacity="0.12" stroke="white" strokeWidth="1.5" />
      <circle cx="20" cy="20" r="5.5" fill="white" opacity="0.9" />
      <circle cx="22" cy="17.5" r="1.5" fill="white" opacity="0.6" />
      <circle cx="20" cy="20" r="2.5" fill="white" opacity="0.2" />
    </svg>
  )
}

// 7 — Compass Star: eight-point star with center
function IconCompass({ id, c1, c2 }: DrawProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none">
      <BgRect id={id} c1={c1} c2={c2} />
      <path d="M20 8 L20 32" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <path d="M8 20 L32 20" stroke="white" strokeWidth="1.5" opacity="0.45" />
      <path d="M11.5 11.5 L28.5 28.5" stroke="white" strokeWidth="1" opacity="0.3" />
      <path d="M28.5 11.5 L11.5 28.5" stroke="white" strokeWidth="1" opacity="0.3" />
      <circle cx="20" cy="20" r="5" stroke="white" strokeWidth="1.5" opacity="0.6" fill="none" />
      <circle cx="20" cy="20" r="2.5" fill="white" opacity="0.95" />
    </svg>
  )
}

const ICON_TYPES = [
  IconOrb, IconGem, IconNetwork, IconSpiral,
  IconLightning, IconWaves, IconEye, IconCompass,
]

interface AgentIconProps {
  name: string
  /** A unique key to namespace gradient IDs when the same name appears multiple times */
  uid?: string
  className?: string
  size?: number
  /** Use pixel-art character illustration (for global agents) */
  global?: boolean
}

/** Pixel-art character avatar via DiceBear API — used for global agents */
function PixelArtIcon({ name, size }: { name: string; size: number }) {
  const seed = encodeURIComponent(name.toLowerCase().replace(/[^a-z0-9-]/g, '-'))
  return (
    <div
      className="shrink-0 rounded-xl overflow-hidden bg-[#e8e8f8]"
      style={{ width: size, height: size }}
    >
      <img
        src={`https://api.dicebear.com/9.x/pixel-art/svg?seed=${seed}&size=${size * 2}&backgroundColor=e8e8f8`}
        alt={name}
        width={size}
        height={size}
        loading="lazy"
        decoding="async"
        style={{ display: 'block' }}
      />
    </div>
  )
}

export default function AgentIcon({ name, uid, className = '', size = 40, global: isGlobal = false }: AgentIconProps) {
  if (isGlobal) {
    return <PixelArtIcon name={name} size={size} />
  }

  const h = nameHash(name)
  const IconComp = ICON_TYPES[h % ICON_TYPES.length]
  const [c1, c2] = PALETTES[(h >> 4) % PALETTES.length]
  const safeId = (uid || name).replace(/[^a-z0-9]/gi, '-').slice(0, 28)

  return (
    <div
      className={`shrink-0 rounded-xl shadow-sm overflow-hidden ${className}`}
      style={{ width: size, height: size }}
    >
      <IconComp id={safeId} c1={c1} c2={c2} />
    </div>
  )
}

