/**
 * AgentIcon — Illustrated agent icons.
 * Global agents → pixel-art character (DiceBear).
 * Project agents → abstract SVG shape on a gradient card.
 *
 * Both styles use the same padded-card container so they look
 * visually consistent everywhere in the app.
 */

const PALETTES: [string, string][] = [
  ['#7c3aed', '#4f46e5'],
  ['#ec4899', '#f97316'],
  ['#10b981', '#0891b2'],
  ['#0ea5e9', '#6366f1'],
  ['#f59e0b', '#ef4444'],
  ['#14b8a6', '#3b82f6'],
  ['#a855f7', '#ec4899'],
  ['#f97316', '#facc15'],
  ['#06b6d4', '#8b5cf6'],
  ['#84cc16', '#14b8a6'],
]

function nameHash(name: string): number {
  let h = 0
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xffff
  return h
}

// ─── Abstract SVG shapes (no background — container supplies it) ─────────────

// 0: Radiant Orb
function ShapeOrb() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <circle cx="20" cy="20" r="11" fill="white" opacity="0.12" />
      <circle cx="20" cy="20" r="6.5" fill="white" opacity="0.95" />
      <ellipse cx="20" cy="20" rx="12" ry="4.5" stroke="white" strokeWidth="1.6" opacity="0.5" transform="rotate(-25 20 20)" />
      <circle cx="16" cy="16" r="1.8" fill="white" opacity="0.7" />
    </svg>
  )
}

// 1: Crystal/Gem
function ShapeGem() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M20 7 L32 20 L20 33 L8 20 Z" fill="white" opacity="0.14" stroke="white" strokeWidth="1.5" strokeLinejoin="round" />
      <path d="M20 7 L8 20 M20 7 L32 20" stroke="white" strokeWidth="1" opacity="0.5" />
      <path d="M8 20 L20 14.5 L32 20" stroke="white" strokeWidth="1" opacity="0.5" />
      <circle cx="20" cy="17" r="2.2" fill="white" opacity="0.92" />
    </svg>
  )
}

// 2: Neural Network
function ShapeNetwork() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <line x1="20" y1="20" x2="10" y2="11" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="20" y1="20" x2="30" y2="11" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="20" y1="20" x2="10" y2="29" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="20" y1="20" x2="30" y2="29" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="10" y1="11" x2="30" y2="11" stroke="white" strokeWidth="1" opacity="0.22" />
      <line x1="10" y1="29" x2="30" y2="29" stroke="white" strokeWidth="1" opacity="0.22" />
      <circle cx="20" cy="20" r="4.5" fill="white" opacity="0.95" />
      <circle cx="10" cy="11" r="2.5" fill="white" opacity="0.8" />
      <circle cx="30" cy="11" r="2.5" fill="white" opacity="0.8" />
      <circle cx="10" cy="29" r="2.5" fill="white" opacity="0.8" />
      <circle cx="30" cy="29" r="2.5" fill="white" opacity="0.8" />
    </svg>
  )
}

// 3: Spiral/Vortex
function ShapeSpiral() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M20 20 C20 14 26 14 26 20 C26 26 14 26 14 20 C14 14 18.5 10.5 20 10" stroke="white" strokeWidth="2" fill="none" opacity="0.75" strokeLinecap="round" />
      <path d="M20 20 C20 10 30 10 30 20 C30 30 10 30 10 20 C10 11 16 7.5 20 7" stroke="white" strokeWidth="1.5" fill="none" opacity="0.38" strokeLinecap="round" />
      <circle cx="20" cy="20" r="2.8" fill="white" opacity="0.95" />
    </svg>
  )
}

// 4: Lightning Bolt
function ShapeLightning() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M24 7 L13 21.5 L20 21.5 L16.5 33 L27 18.5 L20 18.5 Z" fill="white" opacity="0.95" />
      <circle cx="29.5" cy="10.5" r="1.8" fill="white" opacity="0.55" />
      <circle cx="10" cy="27" r="1.5" fill="white" opacity="0.5" />
      <circle cx="31" cy="29" r="1.1" fill="white" opacity="0.4" />
    </svg>
  )
}

// 5: Waves/Flow
function ShapeWaves() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M6 14 C10 9.5 15 9.5 20 14 C25 18.5 30 18.5 34 14" stroke="white" strokeWidth="2.5" fill="none" opacity="0.92" strokeLinecap="round" />
      <path d="M6 21 C10 16.5 15 16.5 20 21 C25 25.5 30 25.5 34 21" stroke="white" strokeWidth="2" fill="none" opacity="0.55" strokeLinecap="round" />
      <path d="M6 28 C10 23.5 15 23.5 20 28 C25 32.5 30 32.5 34 28" stroke="white" strokeWidth="1.5" fill="none" opacity="0.28" strokeLinecap="round" />
    </svg>
  )
}

// 6: Eye / Lens
function ShapeEye() {
  return (
