/**
 * AgentIcon — Illustrated agent icons.
 * Global agents → pixel-art character (DiceBear).
 * Project agents → abstract SVG shape on a gradient card.
 *
 * Both styles use the same padded-card container so they look
 * visually consistent everywhere in the app.
 */

const PALETTES: [string, string][] = [
  ['#7c3aed', '#4f46e5'],
  ['#ec4899', '#f97316'],
  ['#10b981', '#0891b2'],
  ['#0ea5e9', '#6366f1'],
  ['#f59e0b', '#ef4444'],
  ['#14b8a6', '#3b82f6'],
  ['#a855f7', '#ec4899'],
  ['#f97316', '#facc15'],
  ['#06b6d4', '#8b5cf6'],
  ['#84cc16', '#14b8a6'],
]

function nameHash(name: string): number {
  let h = 0
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xffff
  return h
}

// ─── Abstract SVG shapes (no background — container supplies it) ─────────────

// 0: Radiant Orb
function ShapeOrb() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <circle cx="20" cy="20" r="11" fill="white" opacity="0.12" />
      <circle cx="20" cy="20" r="6.5" fill="white" opacity="0.95" />
      <ellipse cx="20" cy="20" rx="12" ry="4.5" stroke="white" strokeWidth="1.6" opacity="0.5" transform="rotate(-25 20 20)" />
      <circle cx="16" cy="16" r="1.8" fill="white" opacity="0.7" />
    </svg>
  )
}

// 1: Crystal/Gem
function ShapeGem() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M20 7 L32 20 L20 33 L8 20 Z" fill="white" opacity="0.14" stroke="white" strokeWidth="1.5" strokeLinejoin="round" />
      <path d="M20 7 L8 20 M20 7 L32 20" stroke="white" strokeWidth="1" opacity="0.5" />
      <path d="M8 20 L20 14.5 L32 20" stroke="white" strokeWidth="1" opacity="0.5" />
      <circle cx="20" cy="17" r="2.2" fill="white" opacity="0.92" />
    </svg>
  )
}

// 2: Neural Network
function ShapeNetwork() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <line x1="20" y1="20" x2="10" y2="11" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="20" y1="20" x2="30" y2="11" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="20" y1="20" x2="10" y2="29" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="20" y1="20" x2="30" y2="29" stroke="white" strokeWidth="1.5" opacity="0.4" />
      <line x1="10" y1="11" x2="30" y2="11" stroke="white" strokeWidth="1" opacity="0.22" />
      <line x1="10" y1="29" x2="30" y2="29" stroke="white" strokeWidth="1" opacity="0.22" />
      <circle cx="20" cy="20" r="4.5" fill="white" opacity="0.95" />
      <circle cx="10" cy="11" r="2.5" fill="white" opacity="0.8" />
      <circle cx="30" cy="11" r="2.5" fill="white" opacity="0.8" />
      <circle cx="10" cy="29" r="2.5" fill="white" opacity="0.8" />
      <circle cx="30" cy="29" r="2.5" fill="white" opacity="0.8" />
    </svg>
  )
}

// 3: Spiral/Vortex
function ShapeSpiral() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M20 20 C20 14 26 14 26 20 C26 26 14 26 14 20 C14 14 18.5 10.5 20 10" stroke="white" strokeWidth="2" fill="none" opacity="0.75" strokeLinecap="round" />
      <path d="M20 20 C20 10 30 10 30 20 C30 30 10 30 10 20 C10 11 16 7.5 20 7" stroke="white" strokeWidth="1.5" fill="none" opacity="0.38" strokeLinecap="round" />
      <circle cx="20" cy="20" r="2.8" fill="white" opacity="0.95" />
    </svg>
  )
}

// 4: Lightning Bolt
function ShapeLightning() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M24 7 L13 21.5 L20 21.5 L16.5 33 L27 18.5 L20 18.5 Z" fill="white" opacity="0.95" />
      <circle cx="29.5" cy="10.5" r="1.8" fill="white" opacity="0.55" />
      <circle cx="10" cy="27" r="1.5" fill="white" opacity="0.5" />
      <circle cx="31" cy="29" r="1.1" fill="white" opacity="0.4" />
    </svg>
  )
}

// 5: Waves/Flow
function ShapeWaves() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M6 14 C10 9.5 15 9.5 20 14 C25 18.5 30 18.5 34 14" stroke="white" strokeWidth="2.5" fill="none" opacity="0.92" strokeLinecap="round" />
      <path d="M6 21 C10 16.5 15 16.5 20 21 C25 25.5 30 25.5 34 21" stroke="white" strokeWidth="2" fill="none" opacity="0.55" strokeLinecap="round" />
      <path d="M6 28 C10 23.5 15 23.5 20 28 C25 32.5 30 32.5 34 28" stroke="white" strokeWidth="1.5" fill="none" opacity="0.28" strokeLinecap="round" />
    </svg>
  )
}

// 6: Eye / Lens
function ShapeEye() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <path d="M6 20 C10 12.5 15 9.5 20 9.5 C25 9.5 30 12.5 34 20 C30 27.5 25 30.5 20 30.5 C15 30.5 10 27.5 6 20 Z" fill="white" opacity="0.13" stroke="white" strokeWidth="1.5" />
      <circle cx="20" cy="20" r="6" fill="white" opacity="0.9" />
      <circle cx="22" cy="17.5" r="1.8" fill="white" opacity="0.55" />
    </svg>
  )
}

// 7: Compass Star
function ShapeCompass() {
  return (
    <svg viewBox="0 0 40 40" fill="none" width="100%" height="100%">
      <line x1="20" y1="7" x2="20" y2="33" stroke="white" strokeWidth="1.5" opacity="0.42" />
      <line x1="7" y1="20" x2="33" y2="20" stroke="white" strokeWidth="1.5" opacity="0.42" />
      <line x1="10.5" y1="10.5" x2="29.5" y2="29.5" stroke="white" strokeWidth="1" opacity="0.27" />
      <line x1="29.5" y1="10.5" x2="10.5" y2="29.5" stroke="white" strokeWidth="1" opacity="0.27" />
      <circle cx="20" cy="20" r="5.5" stroke="white" strokeWidth="1.5" opacity="0.6" fill="none" />
      <circle cx="20" cy="20" r="2.5" fill="white" opacity="0.95" />
    </svg>
  )
}

const SHAPES = [
  ShapeOrb, ShapeGem, ShapeNetwork, ShapeSpiral,
  ShapeLightning, ShapeWaves, ShapeEye, ShapeCompass,
]

// ─── Pixel-art icon for global agents ───────────────────────────────────────

function PixelArtIcon({ name, size }: { name: string; size: number }) {
  const seed = encodeURIComponent(name.toLowerCase().replace(/[^a-z0-9-]/g, '-'))
  const imgSize = Math.round(size * 0.72)
  const pad = Math.round((size - imgSize) / 2)

  return (
    <div
      className="shrink-0 rounded-xl border border-white/25 shadow-md"
      style={{
        width: size,
        height: size,
        background: 'linear-gradient(145deg, #ede9fe 0%, #dbeafe 100%)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: pad,
        boxSizing: 'border-box',
        flexShrink: 0,
      }}
    >
      <img
        src={`https://api.dicebear.com/9.x/pixel-art/svg?seed=${seed}&size=${imgSize * 2}&backgroundColor=transparent`}
        alt={name}
        width={imgSize}
        height={imgSize}
        loading="lazy"
        decoding="async"
        style={{ display: 'block', imageRendering: 'pixelated' }}
      />
    </div>
  )
}

// ─── Unified card wrapper for project abstract icons ─────────────────────────

function AbstractIcon({
  name, uid, size, c1, c2,
}: { name: string; uid: string; size: number; c1: string; c2: string }) {
  const Shape = SHAPES[nameHash(name) % SHAPES.length]
  const pad = Math.round(size * 0.14)
  const inner = size - pad * 2

  return (
    <div
      className="shrink-0 rounded-xl border border-white/15 shadow-md"
      style={{
        width: size,
        height: size,
        background: `linear-gradient(135deg, ${c1} 0%, ${c2} 100%)`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: pad,
        boxSizing: 'border-box',
        flexShrink: 0,
      }}
    >
      <div style={{ width: inner, height: inner }}>
        <Shape key={uid} />
      </div>
    </div>
  )
}

// ─── Public component ────────────────────────────────────────────────────────

interface AgentIconProps {
  name: string
  /** Unique key to prevent SVG gradient ID collisions when duplicates appear */
  uid?: string
  className?: string
  size?: number
  /** Render pixel-art character (global agents) */
  global?: boolean
}

export default function AgentIcon({
  name, uid, className = '', size = 40, global: isGlobal = false,
}: AgentIconProps) {
  const safeUid = (uid || name).replace(/[^a-z0-9]/gi, '-').slice(0, 28)

  if (isGlobal) {
    return (
      <div className={className} style={{ flexShrink: 0 }}>
        <PixelArtIcon name={name} size={size} />
      </div>
    )
  }

  const h = nameHash(name)
  const [c1, c2] = PALETTES[(h >> 4) % PALETTES.length]

  return (
    <div className={className} style={{ flexShrink: 0 }}>
      <AbstractIcon name={name} uid={safeUid} size={size} c1={c1} c2={c2} />
    </div>
  )
}

